SELECT CASE WHEN orders.channel IN ('partner', 'store') THEN 'priority' ELSE 'other' END channel_group, COUNT(*) total_count, ROUND(STDDEV(order_items.unit_price), 2) stddev_unit_price FROM order_items RIGHT OUTER JOIN products ON order_items.product_id = products.id INNER JOIN orders ON order_items.order_id = orders.id WHERE order_items.product_id = 17 GROUP BY CASE WHEN orders.channel IN ('partner', 'store') THEN 'priority' ELSE 'other' END;
